// The robot's UDP protocol, and turning poses into servo ticks.
//
// The app and the robot describe a leg pose with different conventions. The
// app uses alpha/beta/gamma (linkage.ts); the robot's firmware stores raw servo
// ticks generated by path_tool's inverse kinematics, which produces servo
// angles j1/j2/j3 in [0, 180] where 90 is the servo's middle:
//
//     j1 = 90 + alpha
//     j2 = 90 - sign * beta
//     j3 = 90 + sign * gamma
//
// where `sign` is the leg's legScale: how that leg's femur and tibia servos are
// mirrored. A servo angle becomes a tick with
//
//     ticks = round(j / 180 * (SERVO_MAX - SERVO_MIN) + SERVO_MIN)
//
// which maps j=90 to 307, matching SERVOMID in the firmware's config.h. Leg and
// joint indices are shared with the firmware (naming.ts).
//
// Packets mirror protocol.h in the firmware: little-endian, unpadded, as its
// #pragma pack(1) structs. Nothing here does I/O: main/robot_link.ts sends them.

import type { Pose } from "./path_generator";
import { DEFAULT_CONFIG, getJointLimits, getLegSigns, type RobotConfig } from "./robot_config";
import { pyRound } from "./util";

export const MAGIC_MOTION = 0xa5;
export const MAGIC_POSE = 0xa6;
export const MAGIC_SESSION = 0xa7;
export const MAGIC_VERSION = 0xa8;

export const POSE_FLAG_SNAP = 0x01;

// Session actions.
export const RT_EXIT = 0;
export const RT_ENTER = 1;
export const RT_RELAX = 2;
export const RT_PING = 3;

/** Convert one leg's angles to the robot's j1/j2/j3 servo angles. */
export function jointAnglesToServoAngles(
    legSign: number,
    coxia: number,
    femur: number,
    tibia: number,
): [number, number, number] {
    return [90.0 + coxia, 90.0 - legSign * femur, 90.0 + legSign * tibia];
}

/** Convert a servo angle in degrees to a PWM tick count, clamped to range. */
export function servoAngleToTicks(angle: number, servoMin = 102, servoMax = 512): number {
    const ticks = pyRound((angle * (servoMax - servoMin)) / 180.0 + servoMin);
    return Math.trunc(Math.min(Math.max(ticks, servoMin), servoMax));
}

/** Clamp angles to the robot's mechanically safe joint range. The app permits
 * far more travel than the hardware has, so this is what keeps an unreachable
 * pose from being sent to the servos as a hard stop. */
export function clampPoseAngles(
    coxia: number,
    femur: number,
    tibia: number,
    robot: RobotConfig = DEFAULT_CONFIG,
): [number, number, number] {
    const l = getJointLimits(robot);
    return [
        Math.min(Math.max(coxia, -l.coxia), l.coxia),
        Math.min(Math.max(femur, -l.femur), l.femur),
        Math.min(Math.max(tibia, -l.tibia), l.tibia),
    ];
}

/** A pose as a flat list of 18 servo ticks, leg-major, matching the firmware's
 * LUT layout. Legs left out stand at zero. */
export function poseToTicks(
    pose: Partial<Pose> | readonly ({ coxia?: number; femur?: number; tibia?: number } | undefined)[],
    robot: RobotConfig = DEFAULT_CONFIG,
): number[] {
    const signs = getLegSigns(robot);
    const ticks: number[] = [];
    for (let leg = 0; leg < 6; leg++) {
        const joints = pose[leg];
        let [coxia, femur, tibia] = [joints?.coxia || 0, joints?.femur || 0, joints?.tibia || 0];
        [coxia, femur, tibia] = clampPoseAngles(coxia, femur, tibia, robot);
        for (const angle of jointAnglesToServoAngles(signs[leg], coxia, femur, tibia)) {
            ticks.push(servoAngleToTicks(angle, robot.servo_min, robot.servo_max));
        }
    }
    return ticks;
}

/** Standby, decoded from the firmware's lut_standby ({307, 239, 273} on an
 * unmirrored leg). Every robot bakes standby from gen_posture(60, 75), whose
 * joint angles do not depend on link lengths, so this is shared; only the
 * mirroring differs, and poseToTicks applies that. */
export const STANDBY_POSE = Array.from({ length: 6 }, (_, id) => ({
    id,
    coxia: 0.0,
    femur: 30.0,
    tibia: -15.0,
}));

const u32 = (value: number) => value >>> 0;

/** 7 bytes: run one of the robot's own gaits, at a speed. */
export function motionPacket(motionId: number, seq: number, speedPct: number): Uint8Array {
    const view = new DataView(new ArrayBuffer(7));
    view.setUint8(0, MAGIC_MOTION);
    view.setUint8(1, motionId);
    view.setUint32(2, u32(seq), true);
    view.setUint8(6, speedPct);
    return new Uint8Array(view.buffer);
}

/** 44 bytes: hold a pose, each servo slewing at most `maxStep` ticks a cycle. */
export function posePacket(ticks: readonly number[], seq: number, maxStep: number, snap = false): Uint8Array {
    const view = new DataView(new ArrayBuffer(8 + 2 * 18));
    view.setUint8(0, MAGIC_POSE);
    view.setUint8(1, snap ? POSE_FLAG_SNAP : 0);
    view.setUint16(2, maxStep, true);
    view.setUint32(4, u32(seq), true);
    ticks.forEach((tick, i) => {
        view.setInt16(8 + 2 * i, tick, true);
    });
    return new Uint8Array(view.buffer);
}

/** 6 bytes: enter, leave or keep up the real-time session. */
export function sessionPacket(action: number, seq: number): Uint8Array {
    const view = new DataView(new ArrayBuffer(6));
    view.setUint8(0, MAGIC_SESSION);
    view.setUint8(1, action);
    view.setUint32(2, u32(seq), true);
    return new Uint8Array(view.buffer);
}

/** 5 bytes: ask the firmware for its version. */
export function versionRequest(seq: number): Uint8Array {
    const view = new DataView(new ArrayBuffer(5));
    view.setUint8(0, MAGIC_VERSION);
    view.setUint32(1, u32(seq), true);
    return new Uint8Array(view.buffer);
}

const VERSION_REPLY_HEAD = 9;

/** Decode the robot's answer to version query `seq`, or null when `data` is
 * not that answer. The build tag follows the 9-byte head as UTF-8. */
export function parseVersionReply(
    data: Uint8Array,
    seq: number,
): { version: string; build: string; protocol: number } | null {
    if (data.length < VERSION_REPLY_HEAD || data[0] !== MAGIC_VERSION) {
        return null;
    }
    const view = new DataView(data.buffer, data.byteOffset, data.byteLength);
    if (view.getUint32(1, true) !== u32(seq)) {
        return null;
    }
    const [protocol, major, minor, patch] = [data[5], data[6], data[7], data[8]];
    return {
        version: `${major}.${minor}.${patch}`,
        build: new TextDecoder("utf-8").decode(data.subarray(VERSION_REPLY_HEAD)),
        protocol,
    };
}
